/* ==========================================================================
   RHW PR9 · CROSS-DEVICE TRANSFER CENTER
   Private file sharing, reviewed section import and conflict-safe merging.
   ========================================================================== */
(function initRhwTransferCenter() {
  'use strict';
  const app = window.RHWV4;
  if (!app) return;

  const MAX_FILE_BYTES = 2 * 1024 * 1024;
  const sectionDefinitions = Object.freeze([
    Object.freeze({ key: 'drafts', label: 'NAMED DRAFTS', detail: 'Saved Forum transmissions', mode: 'MERGE', selected: true }),
    Object.freeze({ key: 'senders', label: 'LOCAL SENDERS', detail: 'Custom identity profiles', mode: 'MERGE', selected: true }),
    Object.freeze({ key: 'priceProfiles', label: 'PRICE PROFILES', detail: 'Saved calculator prices', mode: 'MERGE', selected: true }),
    Object.freeze({ key: 'priceCheckOverrides', label: 'PRICE CHECK', detail: 'Manual source prices', mode: 'MERGE', selected: true }),
    Object.freeze({ key: 'productionOrders', label: 'LEGACY DATA', detail: 'Archived order data from earlier versions', mode: 'MERGE', selected: false }),
    Object.freeze({ key: 'current', label: 'CURRENT MESSAGE', detail: 'Autosaved Forum composer', mode: 'REPLACE', selected: false }),
    Object.freeze({ key: 'shipyardPlanner', label: 'ARCHIVED SHIPYARD PLAN', detail: 'Saved planner data from earlier versions', mode: 'REPLACE', selected: false }),
    Object.freeze({ key: 'newswireDraft', label: 'NEWSWIRE WORK', detail: 'Unpublished working copy', mode: 'REPLACE', selected: false }),
    Object.freeze({ key: 'preferences', label: 'APP SETTINGS', detail: 'Last views and workspace', mode: 'REPLACE', selected: false })
  ]);
  const state = { payload: null, inspection: null, fileName: '', returnFocus: null };

  function backupName() {
    return `rhw-private-backup-${new Date().toISOString().slice(0, 10)}.json`;
  }

  function payloadText(payload = app.storage.exportPayload()) {
    return JSON.stringify(payload, null, 2);
  }

  function buildFile(payload = app.storage.exportPayload()) {
    if (typeof File !== 'function') return null;
    return new File([payloadText(payload)], backupName(), { type: 'application/json', lastModified: Date.now() });
  }

  function setStatus(message, tone = 'ready') {
    const status = document.getElementById('rhwTransferStatus');
    if (!status) return;
    status.textContent = String(message || '');
    status.dataset.tone = tone;
  }

  function downloadBackup(payload = app.storage.exportPayload(), { fallback = false } = {}) {
    const blob = new Blob([payloadText(payload)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = backupName();
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    const message = fallback ? 'FILE SHARE UNAVAILABLE // BACKUP DOWNLOADED INSTEAD' : 'PRIVATE BACKUP DOWNLOADED';
    setStatus(message, fallback ? 'warn' : 'good');
    app.notify(message, fallback ? 'warn' : 'good');
    return { downloaded: true, fallback };
  }

  async function shareBackup() {
    const payload = app.storage.exportPayload();
    const file = buildFile(payload);
    const canShare = file && typeof navigator.share === 'function' && typeof navigator.canShare === 'function' && (() => {
      try { return navigator.canShare({ files: [file] }); }
      catch { return false; }
    })();
    if (!canShare) return downloadBackup(payload, { fallback: true });
    try {
      await navigator.share({
        files: [file],
        title: 'RHW private backup',
        text: 'Private RHW cross-device backup. Import it only on a trusted device.'
      });
      setStatus('PRIVATE BACKUP HANDED TO YOUR SHARE MENU', 'good');
      app.notify('PRIVATE BACKUP SHARED');
      return { shared: true, downloaded: false };
    } catch (error) {
      if (error?.name === 'AbortError') {
        setStatus('SHARE CANCELLED // NO FILE WAS SENT', 'ready');
        return { shared: false, cancelled: true };
      }
      setStatus('SHARE FAILED // BACKUP DOWNLOADED INSTEAD', 'warn');
      return downloadBackup(payload, { fallback: true });
    }
  }

  function mountDialog() {
    if (document.getElementById('rhwTransferDialog')) return;
    const dialog = document.createElement('aside');
    dialog.id = 'rhwTransferDialog';
    dialog.className = 'rhw-transfer-dialog';
    dialog.hidden = true;
    dialog.setAttribute('role', 'dialog');
    dialog.setAttribute('aria-modal', 'true');
    dialog.setAttribute('aria-labelledby', 'rhwTransferDialogTitle');
    dialog.dataset.focusTrap = 'true';
    dialog.innerHTML = `<div class="rhw-transfer-backdrop" data-transfer-close></div>
      <section class="rhw-transfer-sheet">
        <header><div><span>IMPORT REVIEW</span><strong id="rhwTransferDialogTitle">CHOOSE WHAT MOVES TO THIS DEVICE</strong></div><button type="button" data-transfer-close aria-label="Close import review">CLOSE</button></header>
        <div id="rhwTransferFileMeta" class="rhw-transfer-file-meta"></div>
        <div class="rhw-transfer-mode-help"><span><b>MERGE</b> KEEPS LOCAL ITEMS AND ADDS NEWER BACKUP ITEMS.</span><span><b>REPLACE</b> OVERWRITES THAT ONE LOCAL WORKING AREA ONLY.</span></div>
        <div id="rhwTransferSectionList" class="rhw-transfer-section-list"></div>
        <div id="rhwTransferImportWarning" class="rhw-transfer-import-warning" role="status" aria-live="polite"></div>
        <footer><button type="button" data-transfer-close>CANCEL</button><button type="button" id="rhwTransferConfirmBtn" class="comms-primary">IMPORT SELECTED SECTIONS</button></footer>
      </section>`;
    document.body.appendChild(dialog);
    dialog.addEventListener('click', event => {
      if (event.target.closest('[data-transfer-close]')) closePreview();
    });
    document.getElementById('rhwTransferConfirmBtn')?.addEventListener('click', confirmImport);
    document.addEventListener('keydown', event => {
      if (dialog.hidden) return;
      if (event.key === 'Escape') {
        closePreview();
        return;
      }
      if (event.key !== 'Tab') return;
      const focusable = [...dialog.querySelectorAll('button, input:not([disabled]), [tabindex]:not([tabindex="-1"])')]
        .filter(element => !element.hasAttribute('disabled') && element.getClientRects().length);
      if (!focusable.length) return;
      const first = focusable[0];
      const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    });
  }

  function formatExportTime(value) {
    if (!value) return 'UNKNOWN EXPORT TIME';
    try { return new Date(value).toLocaleString('de-DE', { dateStyle: 'medium', timeStyle: 'short' }); }
    catch { return 'UNKNOWN EXPORT TIME'; }
  }

  function renderPreview() {
    const dialog = document.getElementById('rhwTransferDialog');
    const meta = document.getElementById('rhwTransferFileMeta');
    const list = document.getElementById('rhwTransferSectionList');
    const warning = document.getElementById('rhwTransferImportWarning');
    if (!dialog || !meta || !list || !warning || !state.inspection) return false;
    const info = state.inspection;
    meta.innerHTML = `<div><small>FILE</small><strong>${app.util.escape(state.fileName || 'RHW BACKUP')}</strong></div><div><small>SOURCE</small><strong>${app.util.escape(info.appVersion)} // FORMAT V${info.version}</strong></div><div><small>EXPORTED</small><strong>${app.util.escape(formatExportTime(info.exportedAt))}</strong></div>`;
    list.innerHTML = sectionDefinitions.filter(definition => info.availableSections.includes(definition.key)).map(definition => {
      const count = info.sections[definition.key];
      return `<label class="rhw-transfer-section" data-mode="${definition.mode.toLowerCase()}"><input type="checkbox" value="${definition.key}"${definition.selected ? ' checked' : ''}><span class="rhw-transfer-check" aria-hidden="true"></span><span class="rhw-transfer-section-copy"><strong>${definition.label}</strong><small>${definition.detail} // ${count} ${count === 1 ? 'ENTRY' : 'ENTRIES'}</small></span><b>${definition.mode}</b></label>`;
    }).join('');
    warning.textContent = info.containsPrivateContent
      ? 'PRIVACY CHECK // THIS FILE CONTAINS PRIVATE WORK. REVIEW EVERY SELECTED SECTION BEFORE IMPORTING.'
      : 'REVIEW THE SELECTED SECTIONS BEFORE IMPORTING.';
    dialog.hidden = false;
    document.body.classList.add('rhw-transfer-open');
    document.getElementById('rhwTransferConfirmBtn')?.focus();
    return true;
  }

  function closePreview() {
    const dialog = document.getElementById('rhwTransferDialog');
    if (dialog) dialog.hidden = true;
    document.body.classList.remove('rhw-transfer-open');
    state.payload = null;
    state.inspection = null;
    const target = state.returnFocus;
    state.returnFocus = null;
    target?.focus?.();
  }

  function previewPayload(payload, fileName = 'RHW BACKUP') {
    mountDialog();
    state.inspection = app.storage.inspectPayload(payload);
    if (!state.inspection.availableSections.length) throw new Error('BACKUP CONTAINS NO IMPORTABLE SECTIONS');
    state.payload = payload;
    state.fileName = fileName;
    state.returnFocus = document.activeElement;
    if (!renderPreview()) throw new Error('IMPORT REVIEW COULD NOT OPEN');
    setStatus(`REVIEWING ${state.inspection.availableSections.length} BACKUP SECTIONS`, 'warn');
    return state.inspection;
  }

  async function previewFile(file) {
    if (!file || typeof file.text !== 'function') throw new Error('NO BACKUP FILE SELECTED');
    if (file.size > MAX_FILE_BYTES) throw new Error('BACKUP FILE EXCEEDS 2 MB LIMIT');
    if (!/\.json$/i.test(file.name || '')) throw new Error('BACKUP MUST BE A JSON FILE');
    try {
      return previewPayload(JSON.parse(await file.text()), file.name);
    } catch (error) {
      setStatus(`IMPORT REVIEW FAILED // ${String(error?.message || 'INVALID FILE').toUpperCase()}`, 'danger');
      throw error;
    }
  }

  function selectedSections() {
    return [...document.querySelectorAll('#rhwTransferSectionList input:checked')].map(input => input.value);
  }

  function confirmImport() {
    const warning = document.getElementById('rhwTransferImportWarning');
    if (!state.payload) return false;
    const sections = selectedSections();
    if (!sections.length) {
      if (warning) warning.textContent = 'SELECT AT LEAST ONE SECTION OR CANCEL THE IMPORT.';
      return false;
    }
    try {
      const result = app.storage.importPayload(state.payload, { sections });
      app.comms?.renderDrafts?.();
      app.comms?.renderSenderRegistry?.();
      app.comms?.renderForm?.();
      closePreview();
      setStatus(`IMPORT COMPLETE // ${sections.length} SECTIONS REVIEWED`, 'good');
      app.notify(`PRIVATE BACKUP IMPORTED // ${sections.length} SECTIONS`);
      window.dispatchEvent(new CustomEvent('rhw:transfer-imported', { detail: { sections, result } }));
      return result;
    } catch (error) {
      const message = `IMPORT FAILED // ${String(error?.message || 'INVALID BACKUP').toUpperCase()}`;
      if (warning) warning.textContent = message;
      app.notify(message, 'danger');
      return false;
    }
  }

  function selfTest() {
    const failures = [];
    if (typeof app.storage?.inspectPayload !== 'function') failures.push('missing:payload-inspector');
    if (!document.getElementById('rhwTransferCenter')) failures.push('missing:transfer-center');
    if (!document.getElementById('shareCommsCacheBtn')) failures.push('missing:share-control');
    if (!document.getElementById('rhwTransferDialog')) failures.push('missing:import-review');
    if (document.getElementById('rhwTransferDialog')?.dataset.focusTrap !== 'true') failures.push('missing:focus-trap');
    return failures;
  }

  function init() {
    mountDialog();
    return Boolean(document.getElementById('rhwTransferCenter'));
  }

  app.transferCenter = {
    init,
    selfTest,
    buildFile,
    shareBackup,
    downloadBackup,
    previewFile,
    previewPayload,
    confirmImport,
    sectionDefinitions
  };
})();

;

/* SOURCE: js/tools/audit.js */
/* ==========================================================================
   RHW WEB APP · PR11 FULL APP AUDIT
   Repeatable, content-free checks for routes, UI, workflows and local runtime.
   ========================================================================== */
(function initRhwFullAppAudit() {
  'use strict';
  const app = window.RHWV4;
  if (!app || app.fullAudit) return;

  const EXPECTED_ROUTES = app.config.routes;
  const state = { results: [], lastRunAt: 0, running: false, autoRun: false };
  const esc = value => app.util.escape(String(value ?? ''));
  const makeResult = (key, label, tone, status, detail) => ({ key, label, tone, status, detail });
  const totalRoutes = () => Object.values(EXPECTED_ROUTES).reduce((total, routes) => total + routes.length, 0);

  function visible(element) {
    if (!element || element.hidden || element.closest('[hidden]')) return false;
    const style = getComputedStyle(element);
    const rect = element.getBoundingClientRect();
    return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
  }

  function routeTopology() {
    const selectors = {
      command: '[data-command-panel]',
      operations: '[data-operations-panel]',
      pricecheck: '[data-pricecheck-panel]',
      comms: '[data-comms-panel]'
    };
    const discovered = {};
    const missing = [];
    Object.entries(EXPECTED_ROUTES).forEach(([workspace, routes]) => {
      discovered[workspace] = [...document.querySelectorAll(selectors[workspace])]
        .map(panel => panel.dataset[`${workspace}Panel`])
        .filter(node => routes.includes(node));
      routes.forEach(route => {
        if (!discovered[workspace].includes(route)) missing.push(`${workspace}/${route}`);
      });
      if (!document.getElementById(`workspace${workspace[0].toUpperCase()}${workspace.slice(1)}`)) missing.push(`${workspace}/workspace`);
    });
    const found = Object.values(discovered).reduce((total, routes) => total + routes.length, 0);
    return missing.length || found !== totalRoutes()
      ? makeResult('routes', 'ROUTE TOPOLOGY', 'danger', 'INCOMPLETE', `${found} / ${totalRoutes()} expected route panels detected.`)
      : makeResult('routes', 'ROUTE TOPOLOGY', 'good', `${found} MOUNTED`, 'Public route panels are mounted. Navigation behavior is verified separately by browser tests.');
  }

  function moduleContracts() {
    const contracts = [
      app.command?.activate, app.operations?.activate, app.comms?.activate,
      app.storage?.exportPayload, app.storage?.importPayload,
      app.pricecheck?.refresh, app.transferCenter?.previewFile,
      app.legacyArchive?.prepareImport,
      app.discoveryStatus?.init, app.diagnostics?.init,
      window.RHWPWA?.isStandalone
    ];
    const ready = contracts.filter(contract => typeof contract === 'function').length;
    return ready === contracts.length
      ? makeResult('modules', 'MODULE CONTRACTS', 'good', `${ready} READY`, 'Core app and workflow APIs are available.')
      : makeResult('modules', 'MODULE CONTRACTS', 'danger', 'INCOMPLETE', `${ready} / ${contracts.length} required APIs are available.`);
  }

  function activeRouteConsistency() {
    const workspace = app.state.activeWorkspace;
    const meta = {
      command: ['commandNode', 'data-command-panel'],
      operations: ['operationsNode', 'data-operations-panel'],
      pricecheck: ['pricecheckNode', 'data-pricecheck-panel'],
      comms: ['commsNode', 'data-comms-panel']
    }[workspace];
    const workspaces = [...document.querySelectorAll('.app-workspace')].filter(element => !element.hidden);
    const selected = [...document.querySelectorAll('.app-tabs [data-workspace][aria-selected="true"]')];
    const activeNode = meta ? app.state[meta[0]] : '';
    const nodePanels = meta ? [...document.querySelectorAll(`[${meta[1]}]`)].filter(element => !element.hidden) : [];
    const route = app.route?.parse?.() || {};
    const matches = workspaces.length === 1 && selected.length === 1 && selected[0].dataset.workspace === workspace &&
      nodePanels.length === 1 && nodePanels[0].dataset[`${workspace}Panel`] === activeNode &&
      route.workspace === workspace && route.node === activeNode;
    return matches
      ? makeResult('active-route', 'ACTIVE ROUTE', 'good', 'SYNCHRONIZED', `${String(workspace || '').toUpperCase()} / ${String(activeNode || '').toUpperCase()} matches UI state.`)
      : makeResult('active-route', 'ACTIVE ROUTE', 'danger', 'STATE MISMATCH', 'URL, selected navigation and visible panel are not synchronized.');
  }

  function domIdentity() {
    const counts = new Map();
    document.querySelectorAll('[id]').forEach(element => counts.set(element.id, (counts.get(element.id) || 0) + 1));
    const duplicates = [...counts.values()].filter(count => count > 1).length;
    let brokenRefs = 0;
    document.querySelectorAll('[aria-controls],[aria-labelledby]').forEach(element => {
      ['aria-controls', 'aria-labelledby'].forEach(attribute => {
        String(element.getAttribute(attribute) || '').split(/\s+/).filter(Boolean).forEach(id => {
          if (!document.getElementById(id)) brokenRefs += 1;
        });
      });
    });
    return duplicates || brokenRefs
      ? makeResult('dom', 'DOM IDENTITY + LINKS', 'danger', 'INVALID', `${duplicates} duplicate ID group(s); ${brokenRefs} broken ARIA reference(s).`)
      : makeResult('dom', 'DOM IDENTITY + LINKS', 'good', 'VALID', 'IDs are unique and labelled controls resolve to mounted elements.');
  }

  function controlName(element) {
    const explicit = element.getAttribute('aria-label') || element.getAttribute('title');
    if (explicit?.trim()) return explicit.trim();
    const labelled = String(element.getAttribute('aria-labelledby') || '').split(/\s+/).filter(Boolean).map(id => document.getElementById(id)?.textContent || '').join(' ').trim();
    if (labelled) return labelled;
    if (['BUTTON', 'A', 'SUMMARY'].includes(element.tagName) && element.textContent.trim()) return element.textContent.trim();
    if (element.id) {
      const label = document.querySelector(`label[for="${CSS.escape(element.id)}"]`);
      if (label?.textContent.trim()) return label.textContent.trim();
    }
    const parentLabel = element.closest('label');
    if (parentLabel?.textContent.trim()) return parentLabel.textContent.trim();
    return element.getAttribute('placeholder') || '';
  }

  function accessibleControls() {
    const controls = [...document.querySelectorAll('button,a[href],input:not([type="hidden"]),select,textarea,summary')]
      .filter(visible);
    const unnamed = controls.filter(element => !controlName(element)).length;
    return unnamed
      ? makeResult('controls', 'CONTROL NAMES', 'warn', `${unnamed} REVIEW`, `${controls.length - unnamed} / ${controls.length} controls expose a readable name.`)
      : makeResult('controls', 'CONTROL NAMES', 'good', `${controls.length} READY`, 'Interactive controls expose a readable name.');
  }

  function dialogSafety() {
    const dialogs = [...document.querySelectorAll('[role="dialog"][aria-modal="true"]')];
    const invalid = dialogs.filter(dialog => {
      const labelId = dialog.getAttribute('aria-labelledby');
      return !labelId || !document.getElementById(labelId) || dialog.dataset.focusTrap !== 'true';
    }).length;
    return invalid
      ? makeResult('dialogs', 'MODAL DIALOGS', 'danger', 'UNSAFE', `${invalid} / ${dialogs.length} modal dialogs need labelled focus containment.`)
      : makeResult('dialogs', 'MODAL DIALOGS', 'good', `${dialogs.length} SAFE`, 'Modal dialogs are labelled and keep keyboard focus inside.');
  }

  function viewportHealth() {
    const overflow = Math.max(document.documentElement.scrollWidth, document.body?.scrollWidth || 0) - window.innerWidth;
    return overflow > 2
      ? makeResult('viewport', 'VIEWPORT FIT', 'danger', 'OVERFLOW', `${Math.ceil(overflow)} px horizontal overflow at ${window.innerWidth} px.`)
      : makeResult('viewport', 'VIEWPORT FIT', 'good', `${window.innerWidth} PX FIT`, 'No horizontal document overflow detected.');
  }

  function touchTargets() {
    if (window.innerWidth > 760) return makeResult('touch', 'TOUCH TARGETS', 'good', 'DESKTOP', 'Mobile target sizing is checked at 760 px and below.');
    const controls = [...document.querySelectorAll('button,a[href],input,select,textarea,summary')].filter(visible);
    const small = controls.filter(element => {
      const rect = element.getBoundingClientRect();
      return rect.width < 43.5 || rect.height < 43.5;
    }).length;
    return small
      ? makeResult('touch', 'TOUCH TARGETS', 'warn', `${small} COMPACT`, `${controls.length - small} / ${controls.length} visible targets meet the 44 px comfort size.`)
      : makeResult('touch', 'TOUCH TARGETS', 'good', `${controls.length} READY`, 'Visible controls meet the 44 px mobile comfort size.');
  }

  function motionContract() {
    const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const applied = document.documentElement.classList.contains('eco');
    if (reduced && !applied) return makeResult('motion', 'REDUCED MOTION', 'danger', 'NOT APPLIED', 'The operating-system motion preference is not active in the app.');
    return makeResult('motion', 'REDUCED MOTION', 'good', reduced ? 'SYSTEM ACTIVE' : applied ? 'ECO ACTIVE' : 'FULL FX', reduced ? 'The operating-system accessibility preference is authoritative.' : 'The current animation preference is applied.');
  }

  function forumParity() {
    try {
      const sample = {
        ...app.state.comms,
        recipient: 'AUDIT RECIPIENT', subject: 'AUDIT SUBJECT', message: 'AUDIT MESSAGE',
        classification: app.state.comms?.classification || 'RHW OFFICIAL'
      };
      const output = app.comms.buildBbcode(sample);
      const ready = ['AUDIT RECIPIENT', 'AUDIT SUBJECT', 'AUDIT MESSAGE'].every(marker => output.includes(marker));
      return ready
        ? makeResult('forum-parity', 'FORUM BB CODE', 'good', 'SYNCHRONIZED', 'Recipient, subject and message survive the shared forum builder.')
        : makeResult('forum-parity', 'FORUM BB CODE', 'danger', 'PARITY FAILED', 'A synthetic field did not reach forum output.');
    } catch {
      return makeResult('forum-parity', 'FORUM BB CODE', 'danger', 'BUILDER ERROR', 'The forum output contract could not complete.');
    }
  }


  function priceCheckContract() {
    const failures = app.pricecheck?.selfTest?.() || ['module'];
    return failures.length
      ? makeResult('pricecheck', 'PRICE CHECK', 'danger', 'INCOMPLETE', 'Fixed-route controls or data contracts are unavailable.')
      : makeResult('pricecheck', 'PRICE CHECK', 'good', 'READY', 'Fixed routes, manual prices and data provenance are available.');
  }

  function catalogTruth() {
    const meta = app.operationsCore?.state?.catalog?.meta || {};
    const recipes = Number(meta.recipeCount) || 0;
    const products = Number(meta.productCount) || 0;
    const effective = app.discoveryStatus?.state?.status?.catalog?.effective;
    const agrees = !effective || ((Number(effective.recipes) || 0) === recipes && (Number(effective.products) || 0) === products);
    if (!recipes || !products) return makeResult('catalog-truth', 'CATALOG DATA TRUTH', 'danger', 'MISSING', 'Recipe or product counts are unavailable.');
    return agrees
      ? makeResult('catalog-truth', 'CATALOG DATA TRUTH', 'good', `${recipes} RECIPES`, `${products} build targets agree with the active Discovery status.`)
      : makeResult('catalog-truth', 'CATALOG DATA TRUTH', 'danger', 'COUNT MISMATCH', 'Runtime catalog counts and Discovery status disagree.');
  }

  function localSaveProbe() {
    const key = `rhw-webapp-v4:full-audit:${Date.now()}`;
    try {
      localStorage.setItem(key, 'ready');
      const ready = localStorage.getItem(key) === 'ready';
      localStorage.removeItem(key);
      return ready
        ? makeResult('local-save', 'LOCAL SAVE PROBE', 'good', 'READ + WRITE', 'Temporary device storage passed a content-free readback test.')
        : makeResult('local-save', 'LOCAL SAVE PROBE', 'danger', 'READBACK FAILED', 'Temporary device storage did not return the written probe.');
    } catch {
      try { localStorage.removeItem(key); } catch {}
      const deployedOrigin = ['http:', 'https:'].includes(location.protocol);
      return deployedOrigin
        ? makeResult('local-save', 'LOCAL SAVE PROBE', 'danger', 'UNAVAILABLE', 'Browser storage is blocked or unavailable.')
        : makeResult('local-save', 'LOCAL SAVE PROBE', 'warn', 'NOT TESTABLE', 'This non-web test origin does not provide browser storage.');
    }
  }

  function pwaContract() {
    const api = window.RHWPWA;
    const manifest = document.querySelector('link[rel="manifest"]');
    const ready = manifest && typeof api?.isStandalone === 'function' && typeof api?.showInstallHelp === 'function';
    return ready
      ? makeResult('pwa-contract', 'APP INSTALL CONTRACT', 'good', api.isStandalone() ? 'STANDALONE' : 'READY', 'Manifest and install helpers are available.')
      : makeResult('pwa-contract', 'APP INSTALL CONTRACT', 'danger', 'INCOMPLETE', 'Manifest or installed-app helper is missing.');
  }

  function collect() {
    return [
      routeTopology(), moduleContracts(), activeRouteConsistency(), domIdentity(), accessibleControls(),
      dialogSafety(), viewportHealth(), touchTargets(), motionContract(), forumParity(),
      priceCheckContract(), catalogTruth(), localSaveProbe(), pwaContract()
    ];
  }

  function summary(results = state.results) {
    return results.reduce((totals, item) => {
      totals.total += 1;
      if (item.tone === 'danger') totals.fail += 1;
      else if (item.tone === 'warn') totals.warn += 1;
      else totals.pass += 1;
      return totals;
    }, { total: 0, pass: 0, warn: 0, fail: 0 });
  }

  function resultMarkup(item) {
    return `<article class="rhw-full-audit-result" data-tone="${esc(item.tone)}" data-audit="${esc(item.key)}"><div><small>${esc(item.label)}</small><strong>${esc(item.status)}</strong></div><span>${esc(item.detail)}</span></article>`;
  }

  function render(results = state.results) {
    const totals = summary(results);
    [['rhwAuditTotal', totals.total], ['rhwAuditPass', totals.pass], ['rhwAuditWarn', totals.warn], ['rhwAuditFail', totals.fail]].forEach(([id, value]) => {
      const element = document.getElementById(id);
      if (element) element.textContent = String(value);
    });
    const list = document.getElementById('rhwFullAuditResults');
    if (list) list.innerHTML = results.length ? results.map(resultMarkup).join('') : '<p class="rhw-full-audit-empty">NOT RUN THIS SESSION</p>';
    const status = document.getElementById('rhwFullAuditStatus');
    if (status) {
      status.dataset.tone = totals.fail ? 'danger' : totals.warn ? 'warn' : results.length ? 'good' : 'muted';
      status.textContent = results.length
        ? totals.fail ? `${totals.fail} BLOCKING FAILURE${totals.fail === 1 ? '' : 'S'}` : totals.warn ? `PASS // ${totals.warn} NOTICE${totals.warn === 1 ? '' : 'S'}` : 'ALL AUDIT CHECKS PASSED'
        : 'READY';
    }
    return totals;
  }

  function buildReport(results = state.results) {
    const totals = summary(results);
    const route = app.route?.parse?.() || {};
    return [
      'RHW FULL APP AUDIT',
      `GENERATED: ${new Date().toISOString()}`,
      `APP: ${app.version}`,
      `ROUTE: ${route.workspace || 'unknown'} / ${route.node || 'unknown'}`,
      `VIEWPORT: ${window.innerWidth} x ${window.innerHeight}`,
      `SUMMARY: ${totals.pass} PASS // ${totals.warn} NOTICE // ${totals.fail} FAIL`,
      '',
      ...results.map(item => `${item.label}: ${item.status} // ${item.detail}`),
      '',
      'PRIVACY: This audit uses synthetic markers and numeric structure checks only. It contains no drafts, messages, sender profiles, material prices or inventory values.'
    ].join('\n');
  }

  async function copyReport() {
    const results = state.results.length ? state.results : await run();
    const copied = await app.util.copy(buildReport(results));
    const status = document.getElementById('rhwFullAuditStatus');
    if (status) {
      status.dataset.tone = copied ? 'good' : 'warn';
      status.textContent = copied ? 'AUDIT REPORT COPIED' : 'COPY NOT AVAILABLE';
    }
    return copied;
  }

  async function run() {
    if (state.running) return state.results;
    state.running = true;
    const button = document.getElementById('rhwFullAuditRun');
    if (button) { button.disabled = true; button.textContent = 'SCANNING…'; }
    const status = document.getElementById('rhwFullAuditStatus');
    if (status) { status.dataset.tone = 'muted'; status.textContent = 'SCANNING APP SHELL…'; }
    await new Promise(resolve => requestAnimationFrame(() => resolve()));
    state.results = collect();
    state.lastRunAt = Date.now();
    state.running = false;
    if (button) { button.disabled = false; button.textContent = 'RUN FULL AUDIT'; }
    render();
    return [...state.results];
  }

  function installSemantics() {
    document.querySelectorAll('.app-tabs [data-workspace]').forEach(button => {
      const workspace = button.dataset.workspace;
      button.id ||= `workspace${workspace[0].toUpperCase()}${workspace.slice(1)}Tab`;
      document.getElementById(button.getAttribute('aria-controls'))?.setAttribute('aria-labelledby', button.id);
    });
    const diagnostics = document.getElementById('rhwDiagnosticsPanel');
    if (diagnostics) diagnostics.dataset.focusTrap = 'true';
  }

  function mount() {
    const panel = document.getElementById('rhwDiagnosticsPanel');
    const before = panel?.querySelector('.rhw-diagnostics-events');
    if (!panel || !before) return false;
    if (!document.getElementById('rhwFullAudit')) {
      before.insertAdjacentHTML('beforebegin', `<section class="rhw-full-audit" id="rhwFullAudit" aria-labelledby="rhwFullAuditTitle"><header><div><strong id="rhwFullAuditTitle">FULL APP AUDIT</strong></div><span id="rhwFullAuditStatus" data-tone="muted" aria-live="polite">READY</span></header><div class="rhw-full-audit-actions"><button type="button" id="rhwFullAuditRun">RUN FULL AUDIT</button><button type="button" id="rhwFullAuditCopy">COPY AUDIT</button></div><div class="rhw-full-audit-metrics"><div><small>TOTAL</small><strong id="rhwAuditTotal">0</strong></div><div data-tone="good"><small>PASS</small><strong id="rhwAuditPass">0</strong></div><div data-tone="warn"><small>NOTICE</small><strong id="rhwAuditWarn">0</strong></div><div data-tone="danger"><small>FAIL</small><strong id="rhwAuditFail">0</strong></div></div><div class="rhw-full-audit-results" id="rhwFullAuditResults"><p class="rhw-full-audit-empty">NOT RUN THIS SESSION</p></div></section>`);
    }
    document.getElementById('rhwFullAuditRun')?.addEventListener('click', run);
    document.getElementById('rhwFullAuditCopy')?.addEventListener('click', copyReport);
    document.getElementById('rhwDiagnosticsBtn')?.addEventListener('click', () => {
      if (state.autoRun) return;
      state.autoRun = true;
      queueMicrotask(run);
    });
    return true;
  }

  function selfTest() {
    const failures = [];
    if (!totalRoutes() || Object.values(EXPECTED_ROUTES).some(routes => !routes.length || new Set(routes).size !== routes.length)) failures.push('route-model');
    const sample = summary([
      makeResult('a', 'A', 'good', 'PASS', 'Ready.'),
      makeResult('b', 'B', 'warn', 'NOTICE', 'Review.'),
      makeResult('c', 'C', 'danger', 'FAIL', 'Blocked.')
    ]);
    if (sample.total !== 3 || sample.pass !== 1 || sample.warn !== 1 || sample.fail !== 1) failures.push('summary');
    ['rhwFullAudit', 'rhwFullAuditRun', 'rhwFullAuditCopy', 'rhwFullAuditResults'].forEach(id => {
      if (typeof document !== 'undefined' && document.getElementById('rhwDiagnosticsPanel') && !document.getElementById(id)) failures.push(`missing:${id}`);
    });
    if (!buildReport([]).includes('PRIVACY: This audit uses synthetic markers')) failures.push('privacy-boundary');
    return failures;
  }

  function init() {
    installSemantics();
    return mount();
  }

  app.fullAudit = { EXPECTED_ROUTES, state, init, run, collect, render, summary, buildReport, copyReport, selfTest };
})();

;

/* SOURCE: js/command/status-navigation.js */
/* ==========================================================================
   RHW COMMAND REWORK
   Removes Overview from the visible command flow, promotes the four operational
   areas, keeps legacy overview analysis as an internal status sensor, and moves
   priority actions into a persistent command alert strip.
   ========================================================================== */
(function initRhwCommandRework() {
  'use strict';
  const app = window.RHWV4;
  if (!app?.command || app.commandStatus) return;

  const MODULES = Object.freeze([
    Object.freeze({ key: 'inventory', label: 'INVENTORY', sub: 'STATUS + MANIFEST', index: '01' }),
    Object.freeze({ key: 'shipyard', label: 'SHIPYARD', sub: 'HULLS + COMPONENTS', index: '02' }),
    Object.freeze({ key: 'production', label: 'PRODUCTION', sub: 'MODULES + CAPACITY + BOTTLENECKS', index: '03' }),
    Object.freeze({ key: 'logistics', label: 'LOGISTICS', sub: 'REMOTE BASES + MARKET + SUPPLY', index: '04' })
  ]);
  let unsubscribeStatus = null;

  function navMarkup() {
    return `<div class="workspace-subnav-tabs command-module-grid">${MODULES.map(module => `
      <button type="button" data-command-node="${module.key}" data-state="waiting" aria-label="${module.label}: ${module.sub}">
        <span class="command-module-index" aria-hidden="true">${module.index}</span>
        <span class="command-module-copy"><strong>${module.label}</strong><small>${module.sub}</small></span>
        <b class="command-module-state" data-command-status="${module.key}">AWAITING DATA</b>
      </button>`).join('')}</div>`;
  }

  function buildNavigation() {
    const nav = document.getElementById('commandNodeNav');
    if (!nav) return false;
    nav.classList.add('command-module-nav');
    nav.setAttribute('aria-label', 'Command operational areas');
    nav.innerHTML = navMarkup();
    if (nav.dataset.commandReworkKeys !== 'true') {
      nav.dataset.commandReworkKeys = 'true';
      nav.addEventListener('keydown', event => {
        const button = event.target.closest('[data-command-node]');
        if (!button || !['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) return;
        const buttons = [...nav.querySelectorAll('[data-command-node]')];
        const current = buttons.indexOf(button);
        if (current < 0) return;
        event.preventDefault();
        let nextIndex = current;
        if (event.key === 'Home') nextIndex = 0;
        else if (event.key === 'End') nextIndex = buttons.length - 1;
        else if (event.key === 'ArrowLeft') nextIndex = (current - 1 + buttons.length) % buttons.length;
        else if (event.key === 'ArrowRight') nextIndex = (current + 1) % buttons.length;
        else if (event.key === 'ArrowUp') nextIndex = (current - 2 + buttons.length) % buttons.length;
        else if (event.key === 'ArrowDown') nextIndex = (current + 2) % buttons.length;
        buttons[nextIndex]?.focus();
      });
    }
    return true;
  }

  function movePriorityActions() {
    const host = document.getElementById('commandNodeHost');
    const overview = document.querySelector('[data-command-panel="overview"]');
    if (!host || !overview) return false;
    overview.classList.add('command-overview-sensor');
    overview.setAttribute('aria-hidden', 'true');

    let panel = document.getElementById('commandGlobalAlerts');
    if (!panel) {
      panel = overview.querySelector('.command-priority-panel');
      if (!panel) return false;
      panel.id = 'commandGlobalAlerts';
      panel.classList.add('command-global-alerts');
      panel.dataset.alertState = 'clear';
      panel.dataset.alertCount = '0';
      const head = panel.querySelector('.command-priority-head');
      if (head) head.innerHTML = `<button type="button" class="command-alert-toggle" id="commandAlertToggle" aria-expanded="false" aria-controls="v40PriorityList">
        <i class="command-alert-signal" aria-hidden="true"></i>
        <span class="command-alert-copy"><strong>ATTENTION</strong><small>PRIORITY ACTIONS FROM CURRENT VERIFIED STATUS</small></span>
        <span class="command-alert-meta"><b id="v40PriorityCount">0 ACTIVE</b><i class="command-alert-chevron" aria-hidden="true">⌄</i></span>
      </button>`;
      host.insertAdjacentElement('beforebegin', panel);
      document.getElementById('commandAlertToggle')?.addEventListener('click', () => {
        const expanded = panel.classList.toggle('expanded');
        document.getElementById('commandAlertToggle')?.setAttribute('aria-expanded', expanded ? 'true' : 'false');
      });
      panel.addEventListener('click', event => {
        const target = event.target.closest('[data-priority-jump]');
        if (target?.dataset.priorityJump) app.navigate('command', target.dataset.priorityJump);
      });
    }
    return true;
  }

  function syncAlertState() {
    const panel = document.getElementById('commandGlobalAlerts');
    const list = document.getElementById('v40PriorityList');
    if (!panel || !list) return;
    const items = [...list.querySelectorAll('.command-priority-item')];
    const state = items.some(item => item.classList.contains('state-critical')) ? 'critical'
      : items.some(item => item.classList.contains('state-low')) ? 'low' : 'clear';
    panel.dataset.alertState = state;
    panel.dataset.alertCount = String(items.length);
    const hint = panel.querySelector('.command-alert-copy small');
    if (hint) hint.textContent = items.length
      ? items[0].querySelector('strong')?.textContent || 'OPEN PRIORITY ACTIONS'
      : 'NO PRIORITY ACTIONS // MONITORED THRESHOLDS NOMINAL';
    if (hint) hint.title = hint.textContent;
    if (items.length === 0) {
      panel.classList.remove('expanded');
      document.getElementById('commandAlertToggle')?.setAttribute('aria-expanded', 'false');
    }
  }

  function syncModuleStatuses() {
    try { app.command.updateOverview?.(); } catch {}
    MODULES.forEach(module => {
      const source = document.querySelector(`.command-overview-card[data-command-jump="${module.key}"]`);
      const button = document.querySelector(`#commandNodeNav [data-command-node="${module.key}"]`);
      const status = button?.querySelector(`[data-command-status="${module.key}"]`);
      if (!button || !status) return;
      const state = source?.dataset.state || 'waiting';
      const summary = source?.querySelector('strong')?.textContent?.trim() || 'AWAITING DATA';
      button.dataset.state = ['critical', 'low', 'ok', 'waiting'].includes(state) ? state : 'waiting';
      status.textContent = summary;
    });
    syncAlertState();
  }

  function selfTest() {
    const failures = [];
    const visibleButtons = [...document.querySelectorAll('#commandNodeNav [data-command-node]')];
    if (visibleButtons.length !== 4) failures.push('command-nav-count');
    if (visibleButtons.some(button => button.dataset.commandNode === 'overview')) failures.push('overview-visible');
    if (!document.getElementById('commandGlobalAlerts')) failures.push('alert-strip');
    if (!document.querySelector('[data-command-panel="overview"].command-overview-sensor')) failures.push('overview-sensor');
    if (!document.querySelector('.inventory-view-nav')) failures.push('inventory-view-switch');
    return failures;
  }

  function install() {

    buildNavigation();
    movePriorityActions();
    clearInterval(app.commandOverviewTimer);
    unsubscribeStatus?.();
    syncModuleStatuses();
    unsubscribeStatus = app.onUiUpdate(() => {
      if (app.state.activeWorkspace === 'command') syncModuleStatuses();
    });
    app.command.nodes = MODULES.map(module => [module.key, module.label, module.sub]);
    const failures = selfTest();
    if (failures.length) throw new Error(`COMMAND REWORK SELF TEST FAILED: ${failures.join(', ')}`);
    return true;
  }

  app.lifecycle.on('command:ready', 'command-navigation', 10, install);
  app.lifecycle.on('command:activated', 'command-status', 10, () => {
    requestAnimationFrame(syncModuleStatuses);
  });

  app.commandStatus = {
    modules: MODULES,
    install,
    syncModuleStatuses,
    syncAlertState,
    selfTest
  };
})();

